  const railDegraded = SY_deriveRail({ positions, pricedAsOf: P, goal, marketConditionsCacheInput: cacheAt(200 * 3_600_000), marketConditionsCacheState: "loaded", targetGeneratedAt: P }); // 200h stale → market excluded
