  const pkgSrc = readFileSync(`${process.cwd()}/src/suggestions/klendDirectUsdcRiskEvidencePackage.ts`, "utf8");
  const B = PKG_BINDING, R = PKG_READINESS, D = PKG_DIMENSIONS;
